"""The test client the integration tests use against QA: real HTTP, a real login, one method per call."""
import requests


class ApiError(Exception):
    pass


class RhinoAPI:
    def __init__(self, base_url: str, email: str, password: str):
        self.base_url, self.email, self.password = base_url, email, password
        self._token = None

    def _send(self, method, url, headers, json_body):  # the seam: the only line that touches the network
        return requests.request(method, url, headers=headers, json=json_body, timeout=30)

    def _request_token(self):
        response = self._send("POST", f"{self.base_url}token/", {}, {"username": self.email, "password": self.password})
        return response.json()["token"]

    def make_call(self, method, path, json_body=None):
        self._token = self._token or self._request_token()
        response = self._send(method, f"{self.base_url}{path}", {"Authorization": f"Token {self._token}"}, json_body)
        if response.status_code >= 400:
            raise ApiError(f"{method} {path}: {response.status_code} {response.json()}")
        return response.json()

    def create_project(self, name: str) -> int:
        return self.make_call("POST", "projects/", {"name": name})["id"]

    def list_projects(self) -> list[dict]:
        return self.make_call("GET", "projects/")
